export const REFERENCE_SOURCES: Record<string, string> = {
  "PayPalButtons.tsx": "\"use client\";\n// Portage reference: PayPal buttons for a React or Next.js page, on PayPal's JS SDK v6 through\n// @paypal/react-paypal-js/sdk-v6 (the pattern in PayPal's official v6 samples).\n//\n// Wrap the page (or the part with buttons) in <PayPalCheckoutProvider> once, then put a <PayPalCheckoutButton> where\n// the existing checkout button is. The button sends the same form fields the existing checkout form sends (pass the\n// form's id), so quantity pickers and hidden product fields keep working. The server creates and captures the order;\n// the browser never decides the amount.\nimport { useState, type ReactNode } from \"react\";\nimport { PayPalOneTimePaymentButton, PayPalProvider, type OnApproveDataOneTimePayments } from \"@paypal/react-paypal-js/sdk-v6\";\n\nexport function PayPalCheckoutProvider({\n  clientId,\n  environment = \"sandbox\",\n  children,\n}: {\n  /** The app's public PayPal client ID (it is safe to send to the browser; the secret never is). */\n  clientId: string | undefined;\n  environment?: \"sandbox\" | \"production\";\n  children: ReactNode;\n}) {\n  if (!clientId) return <>{children}</>; // PayPal not configured: the page still works with its other checkout.\n  return (\n    <PayPalProvider clientId={clientId} environment={environment} components={[\"paypal-payments\"]} pageType=\"checkout\">\n      {children}\n    </PayPalProvider>\n  );\n}\n\nexport function PayPalCheckoutButton({\n  createOrderUrl,\n  captureOrderUrl,\n  formId,\n  payload,\n}: {\n  /** Server route that creates the PayPal order and answers { orderId }. */\n  createOrderUrl: string;\n  /** Server route that captures it; \"{orderId}\" is replaced. It answers { redirectUrl } on success. */\n  captureOrderUrl: string;\n  /** Optional id of the existing checkout form whose fields describe what is being bought. */\n  formId?: string;\n  /** Extra fields to send with the create-order request. */\n  payload?: Record<string, string>;\n}) {\n  const [error, setError] = useState<string | null>(null);\n\n  const createOrder = async (): Promise<{ orderId: string }> => {\n    setError(null);\n    const fields: Record<string, string> = { ...payload };\n    const form = formId ? (document.getElementById(formId) as HTMLFormElement | null) : null;\n    if (form) for (const [k, v] of new FormData(form)) if (typeof v === \"string\") fields[k] = v;\n    const res = await fetch(createOrderUrl, { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(fields) });\n    const data = (await res.json().catch(() => ({}))) as { orderId?: string; error?: string };\n    if (!res.ok || !data.orderId) {\n      const message = data.error ?? \"PayPal checkout is unavailable right now.\";\n      setError(message);\n      throw new Error(message);\n    }\n    return { orderId: data.orderId };\n  };\n\n  const onApprove = async ({ orderId }: OnApproveDataOneTimePayments) => {\n    const res = await fetch(captureOrderUrl.replace(\"{orderId}\", encodeURIComponent(orderId)), { method: \"POST\" });\n    const data = (await res.json().catch(() => ({}))) as { redirectUrl?: string; error?: string };\n    if (res.ok && data.redirectUrl) window.location.assign(data.redirectUrl);\n    else setError(data.error ?? \"The payment could not be completed. You have not been charged.\");\n  };\n\n  return (\n    <div className=\"paypal-checkout\">\n      <PayPalOneTimePaymentButton\n        createOrder={createOrder}\n        presentationMode=\"auto\"\n        onApprove={onApprove}\n        onCancel={() => setError(null)}\n        onError={() => setError(\"PayPal ran into a problem. Please try again.\")}\n      />\n      {error ? (\n        <p role=\"alert\" className=\"paypal-error\">\n          {error}\n        </p>\n      ) : null}\n    </div>\n  );\n}\n",
  "paypal-buttons.js": "// Portage reference: PayPal buttons on a server-rendered page (Express, plain HTML), using PayPal's JS SDK v6 with\n// no build step. This follows PayPal's recommended v6 one-time payment sample.\n//\n// On the page:\n//   <meta name=\"paypal-checkout\" data-client-id=\"PUBLIC_CLIENT_ID\" data-currency=\"USD\"\n//         data-create-url=\"/paypal/orders\" data-capture-url=\"/paypal/orders/{orderId}/capture\">\n//   <paypal-button type=\"pay\" class=\"paypal-gold\" data-form=\"ID_OF_THE_EXISTING_CHECKOUT_FORM\" hidden></paypal-button>\n//   <script src=\"/paypal-buttons.js\"></script>\n//   <script async src=\"https://www.sandbox.paypal.com/web-sdk/v6/core\" onload=\"portagePayPalReady()\"></script>\n// (Use https://www.paypal.com/web-sdk/v6/core in production.)\n//\n// Each button sends the fields of its form to the create-order route, which answers { orderId }. After the buyer\n// approves, the capture route answers { redirectUrl }. The server decides the amount, never the browser.\n(function () {\n  \"use strict\";\n\n  function showError(button, message) {\n    var note = button.nextElementSibling;\n    if (!note || !note.classList || !note.classList.contains(\"paypal-error\")) {\n      note = document.createElement(\"p\");\n      note.className = \"paypal-error\";\n      note.setAttribute(\"role\", \"alert\");\n      button.insertAdjacentElement(\"afterend\", note);\n    }\n    note.textContent = message || \"\";\n    note.hidden = !message;\n  }\n\n  function fieldsOf(button) {\n    var fields = {};\n    var form = button.dataset.form ? document.getElementById(button.dataset.form) : null;\n    if (form) {\n      new FormData(form).forEach(function (value, key) {\n        if (typeof value === \"string\") fields[key] = value;\n      });\n    }\n    return fields;\n  }\n\n  async function createOrder(button, createUrl) {\n    showError(button, \"\");\n    var res = await fetch(createUrl, { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(fieldsOf(button)) });\n    var data = await res.json().catch(function () { return {}; });\n    if (!res.ok || !data.orderId) {\n      var message = data.error || \"PayPal checkout is unavailable right now.\";\n      showError(button, message);\n      throw new Error(message);\n    }\n    return { orderId: data.orderId };\n  }\n\n  async function setup() {\n    var config = document.querySelector('meta[name=\"paypal-checkout\"]');\n    if (!config || !window.paypal || !config.dataset.clientId) return;\n    var createUrl = config.dataset.createUrl;\n    var captureUrl = config.dataset.captureUrl;\n\n    var sdk = await window.paypal.createInstance({ clientId: config.dataset.clientId, components: [\"paypal-payments\"], pageType: \"checkout\" });\n    var methods = await sdk.findEligibleMethods({ currencyCode: config.dataset.currency || \"USD\" });\n    if (!methods.isEligible(\"paypal\")) return;\n\n    document.querySelectorAll(\"paypal-button[data-form]\").forEach(function (button) {\n      var session = sdk.createPayPalOneTimePaymentSession({\n        onApprove: async function (data) {\n          var res = await fetch(captureUrl.replace(\"{orderId}\", encodeURIComponent(data.orderId)), { method: \"POST\" });\n          var result = await res.json().catch(function () { return {}; });\n          if (res.ok && result.redirectUrl) window.location.assign(result.redirectUrl);\n          else showError(button, result.error || \"The payment could not be completed. You have not been charged.\");\n        },\n        onCancel: function () { showError(button, \"\"); },\n        onError: function () { showError(button, \"PayPal ran into a problem. Please try again.\"); },\n      });\n      button.removeAttribute(\"hidden\");\n      button.addEventListener(\"click\", async function () {\n        try {\n          // Pass the promise without awaiting it first: awaiting before start() loses the click's popup permission.\n          await session.start({ presentationMode: \"auto\" }, createOrder(button, createUrl));\n        } catch (err) {\n          if (!button.nextElementSibling || button.nextElementSibling.hidden) showError(button, \"PayPal checkout could not start.\");\n          console.error(err);\n        }\n      });\n    });\n  }\n\n  window.portagePayPalReady = function () {\n    setup().catch(function (err) { console.error(\"PayPal buttons could not load\", err); });\n  };\n})();\n",
  "paypal-client.ts": "// Portage reference: one shared PayPal Server SDK client for the app.\n//\n// Every SDK name here was confirmed through ContextMatic (APIMatic Context Plugin): fetch_api paypal,\n// endpoint_search createOrder / captureOrder / refundCapturedPayment / getCapturedPayment, model_search Money.\n// Typechecked against @paypal/paypal-server-sdk 2.x. Adapt the import paths and style to the app; keep the behaviour.\nimport { randomUUID } from \"node:crypto\";\nimport { ApiError, Client, CustomError, Environment, OrdersController, PaymentsController } from \"@paypal/paypal-server-sdk\";\n\n/** \"sandbox\" unless PAYPAL_ENVIRONMENT is explicitly \"live\". */\nexport const paypalEnvironment: \"sandbox\" | \"live\" = process.env.PAYPAL_ENVIRONMENT === \"live\" ? \"live\" : \"sandbox\";\n\nlet client: Client | undefined;\n\n/**\n * The SDK client, created on first use so that importing this module during a build (when PayPal settings may be\n * absent) doesn't throw. The SDK fetches and caches its OAuth token itself.\n */\nexport function paypalClient(): Client {\n  if (client) return client;\n  const oAuthClientId = process.env.PAYPAL_CLIENT_ID;\n  const oAuthClientSecret = process.env.PAYPAL_CLIENT_SECRET;\n  if (!oAuthClientId || !oAuthClientSecret) {\n    throw new Error(\"PayPal is not configured: set PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET\");\n  }\n  client = new Client({\n    clientCredentialsAuthCredentials: { oAuthClientId, oAuthClientSecret },\n    environment: paypalEnvironment === \"live\" ? Environment.Production : Environment.Sandbox,\n    timeout: 15_000,\n    httpClientOptions: {\n      // Retry dropped connections, 429s and 5xx with backoff (PayPal recommends it). POST is included on purpose:\n      // every POST here sends a PayPal-Request-Id, so a retried POST returns the original result instead of\n      // charging twice. The SDK's defaults are no retries, and never for POST.\n      retryConfig: {\n        maxNumberOfRetries: 2,\n        retryOnTimeout: true, // the SDK treats network errors (ECONNRESET, ...) as timeouts\n        maximumRetryWaitTime: 10,\n        httpMethodsToRetry: [\"GET\", \"PUT\", \"POST\", \"PATCH\"],\n      },\n    },\n    // No `logging` option on purpose: with one, the SDK logs every request and response, which can include payer\n    // details. Log failures yourself with describePayPalError.\n  });\n  return client;\n}\n\nexport const ordersApi = (): OrdersController => new OrdersController(paypalClient());\nexport const paymentsApi = (): PaymentsController => new PaymentsController(paypalClient());\n\n/** A fresh PayPal-Request-Id. Send one with every POST; reuse the same value when retrying the same request. */\nexport const paypalRequestId = (): string => randomUUID();\n\n/** A log-safe description of a PayPal error, including PayPal's debug_id, which PayPal support asks for. */\nexport function describePayPalError(err: unknown): string {\n  if (err instanceof ApiError) {\n    // The SDK keeps PayPal's error body as sent (snake_case), and PayPal also returns the id as a header.\n    const r = (err instanceof CustomError ? err.result : undefined) as { name?: string; message?: string; debug_id?: string; details?: { issue?: string }[] } | undefined;\n    const debugId = r?.debug_id ?? err.headers?.[\"paypal-debug-id\"] ?? (typeof err.body === \"string\" ? /\"debug_id\"\\s*:\\s*\"([^\"]+)\"/.exec(err.body)?.[1] : undefined);\n    const issue = r?.details?.[0]?.issue;\n    const detail = [r?.name, issue ?? r?.message, debugId ? `debug_id ${debugId}` : \"\"].filter(Boolean).join(\" · \");\n    return `PayPal API error ${err.statusCode}${detail ? `: ${detail}` : \"\"}`;\n  }\n  return err instanceof Error ? err.message : String(err);\n}\n",
  "paypal-money.ts": "// Portage reference: money conversion between the app's Stripe-style amounts and PayPal amounts.\n//\n// Stripe amounts are integers in the currency's minor unit (\"2400\" = 24.00 USD; \"2400\" = 2400 JPY).\n// PayPal amounts are decimal strings with PayPal's own number of decimals (\"24.00\", \"2400\").\n// They disagree for HUF and TWD (two decimals on Stripe, none on PayPal), so this refuses instead of rounding.\n// Self-contained on purpose: copy it into the app as it is. Portage's tests check it against Portage's own helper.\n\nexport interface PayPalMoney {\n  currencyCode: string;\n  value: string;\n}\n\n/** Decimal places PayPal accepts, per currency it supports (developer.paypal.com/api/rest/reference/currency-codes). */\nconst PAYPAL_DECIMALS: Record<string, number> = {\n  AUD: 2, BRL: 2, CAD: 2, CNY: 2, CZK: 2, DKK: 2, EUR: 2, HKD: 2, HUF: 0, ILS: 2, JPY: 0, MYR: 2, MXN: 2,\n  TWD: 0, NZD: 2, NOK: 2, PHP: 2, PLN: 2, GBP: 2, RUB: 2, SGD: 2, SEK: 2, CHF: 2, THB: 2, USD: 2,\n};\n/** Stripe's zero- and three-decimal currencies (docs.stripe.com/currencies); everything else is two. */\nconst STRIPE_ZERO = new Set([\"BIF\", \"CLP\", \"DJF\", \"GNF\", \"JPY\", \"KMF\", \"KRW\", \"MGA\", \"PYG\", \"RWF\", \"VND\", \"VUV\", \"XAF\", \"XOF\", \"XPF\"]);\nconst STRIPE_THREE = new Set([\"BHD\", \"JOD\", \"KWD\", \"OMR\", \"TND\"]);\n\nconst code = (currency: string): string => {\n  if (!/^[A-Za-z]{3}$/.test(currency)) throw new Error(`\"${currency}\" is not a currency code`);\n  return currency.toUpperCase();\n};\nconst stripeDecimals = (c: string) => (STRIPE_ZERO.has(c) ? 0 : STRIPE_THREE.has(c) ? 3 : 2);\n\nexport function paypalSupportsCurrency(currency: string): boolean {\n  return code(currency) in PAYPAL_DECIMALS;\n}\n\n/** 2400, \"usd\" → { currencyCode: \"USD\", value: \"24.00\" }. Throws for amounts PayPal can't represent exactly. */\nexport function toPayPalMoney(minorUnits: number, currency: string): PayPalMoney {\n  if (!Number.isSafeInteger(minorUnits) || minorUnits < 0) throw new Error(`Amount must be a whole number of minor units, got ${minorUnits}`);\n  const c = code(currency);\n  const pp = PAYPAL_DECIMALS[c];\n  if (pp === undefined) throw new Error(`PayPal does not accept payments in ${c}`);\n  const st = stripeDecimals(c);\n  let units = BigInt(minorUnits);\n  if (st > pp) {\n    const factor = 10n ** BigInt(st - pp);\n    if (units % factor !== 0n) throw new Error(`${minorUnits} (${c} minor units) has no exact PayPal amount: PayPal takes ${pp} decimals for ${c}`);\n    units /= factor;\n  } else if (st < pp) {\n    units *= 10n ** BigInt(pp - st);\n  }\n  return { currencyCode: c, value: format(units, pp) };\n}\n\n/**\n * { currencyCode: \"USD\", value: \"24.00\" } → 2400. Also accepts the snake_case shape PayPal's webhooks and REST\n * responses use ({ currency_code, value }), so SDK results and webhook payloads go through the same helper.\n */\nexport function fromPayPalMoney(money: { currencyCode?: string; currency_code?: string; value?: string }): number {\n  const c = code(money.currencyCode ?? money.currency_code ?? \"\");\n  const pp = PAYPAL_DECIMALS[c];\n  if (pp === undefined) throw new Error(`PayPal does not accept payments in ${c}`);\n  const m = /^(\\d+)(?:\\.(\\d+))?$/.exec(money.value ?? \"\");\n  if (!m || (m[2] ?? \"\").length > pp) throw new Error(`\"${money.value}\" is not a valid ${c} amount`);\n  const st = stripeDecimals(c);\n  const units = BigInt(m[1] + (m[2] ?? \"\").padEnd(pp, \"0\"));\n  const minor = st >= pp ? units * 10n ** BigInt(st - pp) : units / 10n ** BigInt(pp - st);\n  if (st < pp && units % 10n ** BigInt(pp - st) !== 0n) throw new Error(`\"${money.value}\" ${c} has no exact amount in minor units`);\n  if (minor > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error(`\"${money.value}\" is too large`);\n  return Number(minor);\n}\n\nfunction format(units: bigint, decimals: number): string {\n  if (decimals === 0) return units.toString();\n  const s = units.toString().padStart(decimals + 1, \"0\");\n  return `${s.slice(0, -decimals)}.${s.slice(-decimals)}`;\n}\n",
  "paypal-webhook.ts": "// Portage reference: verify a PayPal webhook before trusting it.\n//\n// The PayPal Server SDK has no webhook methods (confirmed through ContextMatic), so this calls PayPal's REST API\n// directly: POST /v1/notifications/verify-webhook-signature, with an OAuth token for the same credentials.\n// The event is passed to PayPal exactly as received (the raw body text), never re-serialised, because PayPal checks\n// the signature over the original bytes.\nimport { randomUUID } from \"node:crypto\";\n\nexport interface PayPalWebhookEvent {\n  id: string;\n  event_type: string;\n  resource_type?: string;\n  resource: Record<string, unknown> & {\n    id?: string;\n    status?: string;\n    custom_id?: string;\n    amount?: { currency_code?: string; value?: string };\n    supplementary_data?: { related_ids?: { order_id?: string } };\n    /** On refund events: total_refunded_amount is the running refunded total for the capture. */\n    seller_payable_breakdown?: { total_refunded_amount?: { currency_code?: string; value?: string } };\n    links?: { href: string; rel: string; method?: string }[];\n  };\n  create_time?: string;\n}\n\nexport type WebhookVerification = { verified: true; event: PayPalWebhookEvent } | { verified: false; reason: string };\n\nconst HEADERS = [\"paypal-transmission-id\", \"paypal-transmission-time\", \"paypal-transmission-sig\", \"paypal-cert-url\", \"paypal-auth-algo\"] as const;\n\n/** PayPal's REST base URL for the configured environment. PAYPAL_API_BASE overrides it (for tests only). */\nexport function paypalApiBase(): string {\n  if (process.env.PAYPAL_API_BASE) return process.env.PAYPAL_API_BASE.replace(/\\/$/, \"\");\n  return process.env.PAYPAL_ENVIRONMENT === \"live\" ? \"https://api-m.paypal.com\" : \"https://api-m.sandbox.paypal.com\";\n}\n\n/**\n * fetch with up to two retries, with backoff, for dropped connections, 429 and 5xx. Safe for these calls: getting a\n * token and verifying a signature change nothing at PayPal.\n */\nasync function fetchWithRetry(url: string, init: RequestInit, attempts = 3): Promise<Response> {\n  for (let i = 0; ; i++) {\n    try {\n      const res = await fetch(url, init);\n      if ((res.status === 429 || res.status >= 500) && i < attempts - 1) {\n        await new Promise((r) => setTimeout(r, 500 * 2 ** i));\n        continue;\n      }\n      return res;\n    } catch (err) {\n      if (i >= attempts - 1) throw err;\n      await new Promise((r) => setTimeout(r, 500 * 2 ** i));\n    }\n  }\n}\n\nlet cached: { token: string; expiresAt: number } | undefined;\n\n/** A client-credentials access token, cached until a minute before it expires (PayPal sends expires_in). */\nexport async function paypalAccessToken(): Promise<string> {\n  if (cached && Date.now() < cached.expiresAt) return cached.token;\n  const id = process.env.PAYPAL_CLIENT_ID;\n  const secret = process.env.PAYPAL_CLIENT_SECRET;\n  if (!id || !secret) throw new Error(\"PayPal is not configured: set PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET\");\n  const res = await fetchWithRetry(`${paypalApiBase()}/v1/oauth2/token`, {\n    method: \"POST\",\n    headers: { Authorization: `Basic ${Buffer.from(`${id}:${secret}`).toString(\"base64\")}`, \"Content-Type\": \"application/x-www-form-urlencoded\" },\n    body: \"grant_type=client_credentials\",\n  });\n  if (!res.ok) throw new Error(`PayPal OAuth failed with HTTP ${res.status}`);\n  const data = (await res.json()) as { access_token: string; expires_in: number };\n  cached = { token: data.access_token, expiresAt: Date.now() + Math.max(0, data.expires_in - 60) * 1000 };\n  return data.access_token;\n}\n\nfunction header(headers: Headers | Record<string, string | string[] | undefined>, name: string): string | undefined {\n  if (typeof (headers as Headers).get === \"function\") return (headers as Headers).get(name) ?? undefined;\n  const record = headers as Record<string, string | string[] | undefined>;\n  const key = Object.keys(record).find((k) => k.toLowerCase() === name);\n  const v = key ? record[key] : undefined;\n  return Array.isArray(v) ? v[0] : v;\n}\n\n/**\n * Verifies a webhook delivery with PayPal.\n * @param headers the request headers (a Fetch `Headers`, or Node/Express `req.headers`)\n * @param rawBody the request body exactly as received, as text\n */\nexport async function verifyPayPalWebhook(headers: Headers | Record<string, string | string[] | undefined>, rawBody: string): Promise<WebhookVerification> {\n  const webhookId = process.env.PAYPAL_WEBHOOK_ID;\n  if (!webhookId) return { verified: false, reason: \"PAYPAL_WEBHOOK_ID is not set\" };\n  const values = HEADERS.map((h) => header(headers, h));\n  if (values.some((v) => !v)) return { verified: false, reason: \"missing PayPal transmission headers\" };\n\n  let event: PayPalWebhookEvent;\n  try {\n    event = JSON.parse(rawBody) as PayPalWebhookEvent;\n  } catch {\n    return { verified: false, reason: \"body is not JSON\" };\n  }\n  if (!event || typeof event.event_type !== \"string\") return { verified: false, reason: \"body is not a PayPal event\" };\n\n  const [transmissionId, transmissionTime, transmissionSig, certUrl, authAlgo] = values as string[];\n  // Splice the raw body in as the event so PayPal sees the original bytes.\n  const body =\n    `{\"auth_algo\":${JSON.stringify(authAlgo)},\"cert_url\":${JSON.stringify(certUrl)},\"transmission_id\":${JSON.stringify(transmissionId)},` +\n    `\"transmission_sig\":${JSON.stringify(transmissionSig)},\"transmission_time\":${JSON.stringify(transmissionTime)},` +\n    `\"webhook_id\":${JSON.stringify(webhookId)},\"webhook_event\":${rawBody}}`;\n\n  const res = await fetchWithRetry(`${paypalApiBase()}/v1/notifications/verify-webhook-signature`, {\n    method: \"POST\",\n    headers: { Authorization: `Bearer ${await paypalAccessToken()}`, \"Content-Type\": \"application/json\", \"PayPal-Request-Id\": randomUUID() },\n    body,\n  });\n  if (!res.ok) {\n    // Say which field PayPal rejected (for example a malformed webhook_id), without echoing any values.\n    const err = (await res.json().catch(() => ({}))) as { name?: string; details?: { field?: string; issue?: string }[] };\n    const d = err.details?.[0];\n    return { verified: false, reason: `verification call failed with HTTP ${res.status}${d ? `: ${d.field ?? \"\"} ${d.issue ?? \"\"}`.trimEnd() : err.name ? `: ${err.name}` : \"\"}` };\n  }\n  const result = (await res.json()) as { verification_status?: string };\n  return result.verification_status === \"SUCCESS\" ? { verified: true, event } : { verified: false, reason: `verification_status ${result.verification_status ?? \"missing\"}` };\n}\n\n/** For PAYMENT.CAPTURE.REFUNDED: the refund's resource links \"up\" to the capture it refunds. */\nexport function capturedPaymentIdOfRefund(event: PayPalWebhookEvent): string | undefined {\n  const up = event.resource.links?.find((l) => l.rel === \"up\" && /\\/captures\\//.test(l.href));\n  return up ? up.href.split(\"/captures/\")[1]?.split(/[/?]/)[0] : undefined;\n}\n",
};
